// Take the newest N posts
const n = $('Set Configuration Parameters').first().json.postCount || 5;
const items = $input.all().slice(0, n).map(i => ({
  title: i.json.title,
  link: i.json.link,
  snippet: (i.json.contentSnippet || '').slice(0, 250),
}));
return [{ json: { posts: items } }];

// Parse AI JSON and shape rows for Pinterest bulk CSV
const board = $('Set Configuration Parameters').first().json.pinterestBoard;
let parsed;
try {
  parsed = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('AI did not return valid JSON. Run again or lower postCount. Raw: ' + String($input.first().json.choices?.[0]?.message?.content).slice(0, 200));
}
const rows = (parsed.pins || []).map(p => ({
  json: {
    'Title': p.title,
    'Media URL': 'https://PASTE-YOUR-PIN-IMAGE-URL.jpg',
    'Pinterest board': board,
    'Description': p.description,
    'Link': p.link,
    'Publish date': '',
    'Keywords': p.keywords,
  }
}));
if (rows.length === 0) throw new Error('No pins generated.');
return rows;
